// ExperimentalSecondaryProgressionsChartRequest Bi-wheel request: natal chart inside, secondary progressed chart outside.
//
// Mirrors `ExperimentalTransitChartRequest`; only the outer wheel differs. The
// progressed instant follows the classic rule used by
// `/api/v1/western/progressions/secondary`: one ephemeris day after birth per
// tropical year of life elapsed at `progression_date`.
type ExperimentalSecondaryProgressionsChartRequest struct {
	// AspectSet `major` draws conjunction/opposition/trine/square/sextile; `major_plus` also draws the quincunx.
	AspectSet              *ExperimentalSecondaryProgressionsChartRequestAspectSet `json:"aspect_set,omitempty"`
	ChartConfig            *ExperimentalChartConfigSettings                        `json:"chart_config,omitempty"`
	CustomHouseBgColor     *string                                                 `json:"custom_house_bg_color,omitempty"`
	CustomHouseColor       *string                                                 `json:"custom_house_color,omitempty"`
	CustomHouseColors      *[]string                                               `json:"custom_house_colors,omitempty"`
	CustomPlanetColor      *string                                                 `json:"custom_planet_color,omitempty"`
	CustomSignBgColor      *string                                                 `json:"custom_sign_bg_color,omitempty"`
	CustomSignColor        *string                                                 `json:"custom_sign_color,omitempty"`
	CustomSignColors       *[]string                                               `json:"custom_sign_colors,omitempty"`
	DstPolicy              *ExperimentalSecondaryProgressionsChartRequestDstPolicy `json:"dst_policy,omitempty"`
	HouseBackgroundOpacity *float64                                                `json:"house_background_opacity,omitempty"`

	// Layout `progressed_outside` (default): French layout with natal planets inside the sign ring and progressed planets on the outer ring. `progressed_inside`: the transits-chart layout, with the progressed planets drawn on the inner lane. Explicit `chart_config.french_style` / `french_transit_natal_planets_inside` values always win.
	Layout           *ExperimentalSecondaryProgressionsChartRequestLayout `json:"layout,omitempty"`
	Natal            ExperimentalNatalChartRequest                        `json:"natal"`
	NatalPlanetColor *string                                              `json:"natal_planet_color,omitempty"`

	// OrbDeg Maximum orb (degrees) for progressed aspect lines. Default 1.0, matching /api/v1/western/progressions/secondary.
	OrbDeg *float64 `json:"orb_deg,omitempty"`

	// OrbSettings Per-aspect orb overrides (degrees) for progressed aspect lines, e.g. {"conjunction": 1.5}.
	OrbSettings           *AspectOrbSettings `json:"orb_settings,omitempty"`
	ProgressedPlanetColor *string            `json:"progressed_planet_color,omitempty"`

	// ProgressionCity Location used for the progressed houses/angles and for interpreting a local `progression_date`. Defaults to the natal location when omitted together with the coordinates.
	ProgressionCity *string `json:"progression_city,omitempty"`

	// ProgressionDate Real-world date the chart is progressed to: `YYYY-MM-DD` (local midnight at the progression location) or an ISO datetime. Defaults to now (UTC).
	ProgressionDate       *string                                                             `json:"progression_date,omitempty"`
	ProgressionLat        *float64                                                            `json:"progression_lat,omitempty"`
	ProgressionLng        *float64                                                            `json:"progression_lng,omitempty"`
	RetrogradeMarkerStyle *ExperimentalSecondaryProgressionsChartRequestRetrogradeMarkerStyle `json:"retrograde_marker_style,omitempty"`
	ShowHouseBackground   *bool                                                               `json:"show_house_background,omitempty"`
	ShowInterAspects      *bool                                                               `json:"show_inter_aspects,omitempty"`
	ShowNatalAspects      *bool                                                               `json:"show_natal_aspects,omitempty"`

	// ShowProgressedAngles Draw the progressed ASC/MC glyphs on the outer wheel (requires a known birth time).
	ShowProgressedAngles  *bool `json:"show_progressed_angles,omitempty"`
	ShowProgressedAspects *bool `json:"show_progressed_aspects,omitempty"`

	// ShowProgressedHouses Draw the progressed house cusps as a secondary house wheel (requires a known birth time). In the default `progressed_outside` layout the cusp ring sits beyond the progressed planets; with `progressed_inside` it sits inside the sign ring.
	ShowProgressedHouses  *bool    `json:"show_progressed_houses,omitempty"`
	ShowRetrogradeMarkers *bool    `json:"show_retrograde_markers,omitempty"`
	ShowSignBackground    *bool    `json:"show_sign_background,omitempty"`
	SignBackgroundOpacity *float64 `json:"sign_background_opacity,omitempty"`

	// TzStr Timezone of `progression_date`. `AUTO` resolves it from the progression location.
	TzStr *string `json:"tz_str,omitempty"`
}

// ExperimentalSecondaryProgressionsChartRequestAspectSet `major` draws conjunction/opposition/trine/square/sextile; `major_plus` also draws the quincunx.
type ExperimentalSecondaryProgressionsChartRequestAspectSet string

